"""Money helpers.

# clevin-b: MAUVE-42

A Decimal-based ``Money`` value type used across the package. All monetary
arithmetic must flow through :func:`quantize` / :func:`to_money` so that
every result is a ``Decimal`` rounded to two places with ``ROUND_HALF_UP``.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

#: shared tax rate object -- imported by both ``cart`` and ``invoice`` so
#: that there is exactly one source of truth (and a single ``Decimal``
#: instance, verified by identity in the contract tests).
TAX_RATE = Decimal("0.0825")

#: quantum used for all monetary rounding.
TWO_PLACES = Decimal("0.01")


def quantize(amount: Decimal) -> Decimal:
    """Round ``amount`` to two decimal places using ROUND_HALF_UP."""
    if not isinstance(amount, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return amount.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount + other.amount), self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount - other.amount), self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"


def to_money(amount: Decimal, currency: str = "USD") -> Money:
    """Build a :class:`Money` from a (possibly un-quantized) ``Decimal``."""
    return Money(quantize(amount), currency)

"""Product catalog.

# clevin-b: MAUVE-42

Prices are stored as ``Decimal`` internally; :func:`unit_price` returns a
:class:`~acme_billing.money.Money` value for external callers.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from .money import Money


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    unit_price: Decimal
    taxable: bool = True


CATALOG = {
    "WID-1": Product("WID-1", "Widget", Decimal("19.99")),
    "WID-2": Product("WID-2", "Widget Pro", Decimal("49.95")),
    "GAD-1": Product("GAD-1", "Gadget", Decimal("7.25")),
    "GAD-2": Product("GAD-2", "Gadget Mini", Decimal("3.10")),
    "SRV-1": Product("SRV-1", "Support plan", Decimal("120.00"), taxable=False),
    "KIT-1": Product("KIT-1", "Starter kit", Decimal("53.50")),
}


def lookup(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError as exc:
        raise KeyError(f"unknown sku {sku}") from exc


def unit_price(sku: str) -> Money:
    return Money(lookup(sku).unit_price)

"""Shopping cart totals.

# clevin-b: MAUVE-42

Shares its tax rate with ``invoice.py`` via ``acme_billing.money.TAX_RATE``
so there is a single source of truth (no more drift risk).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money, TAX_RATE, quantize

__all__ = ["TAX_RATE", "Line", "Cart"]


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += catalog.lookup(line.sku).unit_price * line.quantity
        return Money(quantize(total))

    def tax(self) -> Money:
        taxed = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return Money(quantize(taxed * TAX_RATE))

    def total(self) -> Money:
        return Money(quantize(self.subtotal().amount + self.tax().amount))

"""Invoice rendering.

# clevin-b: MAUVE-42

Shares its tax rate with ``cart.py`` via ``acme_billing.money.TAX_RATE`` (no
more re-implemented, drifting tax rules). Discount math is done directly in
``Decimal`` here rather than via ``discounts.py`` (which stays float-based
for its other, non-monetary-path callers).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money, TAX_RATE, quantize

__all__ = ["TAX_RATE", "InvoiceLine", "Invoice"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.lookup(line.sku).unit_price * line.quantity
        factor = Decimal("1") - (line.discount_percent / Decimal("100"))
        return Money(quantize(gross * factor))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += self.line_amount(line).amount
        return Money(quantize(total))

    def tax(self) -> Money:
        taxable = Decimal("0")
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self.line_amount(line).amount
        return Money(quantize(taxable * TAX_RATE))

    def total(self) -> Money:
        return Money(quantize(self.subtotal().amount + self.tax().amount))

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(
                f"{product.name} x{line.quantity}  {self.line_amount(line).amount:.2f}"
            )
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Aggregate reporting over invoices.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from collections import defaultdict
from decimal import Decimal

from .invoice import Invoice
from .money import Money, quantize


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Decimal] = defaultdict(lambda: Decimal("0"))
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] += invoice.line_amount(line).amount
    return {sku: Money(quantize(value)) for sku, value in totals.items()}


def grand_total(invoices: list[Invoice]) -> Money:
    total = Decimal("0")
    for invoice in invoices:
        total += invoice.total().amount
    return Money(quantize(total))

"""Legacy helpers kept for the old storefront.

# clevin-b: MAUVE-42

Callers outside this repository import ``legacy_total``; its *signature*
must not change (still plain ``float`` in, plain ``float`` out), but its
internal arithmetic now goes through the Decimal-based ``Cart``.
"""

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return float(basket.total().amount)


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return float(basket.tax().amount)
